WITH filtered AS (SELECT *, discount - amount AS discount_minus_amount, ROUND(discount * 0.85, 2) AS discount_adjusted, COALESCE(channel, 'DIRECT') AS channel_filled FROM orders WHERE channel IS DISTINCT FROM 'partner' AND customer_id IS NOT NULL) SELECT status, SUM(CASE WHEN status = 'PENDING' THEN amount ELSE 0 END) AS pending_amount, PERCENTILE_APPROX(shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS shipping_fee_quartiles, COUNT(DISTINCT id) AS distinct_ids FROM filtered GROUP BY status;
